function Logo({ variant = "light", type = "horizontal", width = 96, watermark = false, style = {} }) {
  const isDark = variant === "dark";
  const src = type === "mark" ? LOGOS.mark : LOGOS.horizontal;
  return (
    <img
      src={src}
      alt="Megactivo"
      style={{
        width,
        height: "auto",
        display: "block",
        objectFit: "contain",
        opacity: watermark ? (isDark ? 0.08 : 0.06) : 1,
        filter: !watermark && isDark ? "brightness(0) invert(1)" : "none",
        pointerEvents: "none",
        userSelect: "none",
        ...style,
      }}
    />
  );
}

function BrandWatermark({ variant = "light", position = "right" }) {
  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", pointerEvents: "none" }}>
      <Logo
        type="mark"
        variant={variant}
        watermark
        width={variant === "dark" ? 260 : 230}
        style={{
          position: "absolute",
          right: position === "right" ? -58 : "auto",
          left: position === "left" ? -54 : "auto",
          bottom: -52,
          transform: position === "left" ? "rotate(-6deg)" : "rotate(5deg)",
        }}
      />
      <Logo
        type="mark"
        variant={variant}
        watermark
        width={96}
        style={{ position: "absolute", top: 22, right: 22 }}
      />
    </div>
  );
}

function BrandHeader({ variant = "light", meta }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", position: "relative", zIndex: 2 }}>
      <Logo variant={variant} width={112} />
      {meta && <span style={{ fontSize: T.microSize, color: variant === "dark" ? B.primary : B.text, fontWeight: T.accentWeight }}>{meta}</span>}
    </div>
  );
}

function ProgressDots({ total, idx }) {
  return <div style={{ display: "flex", gap: 4 }}>{Array.from({ length: total }).map((_, i) => <div key={i} style={{ width: i === idx ? 16 : 6, height: 6, borderRadius: 3, background: i === idx ? B.accent : B.lightBg, transition: "all 0.3s" }} />)}</div>;
}

