function CarruselView({ data }) {
  const [idx, setIdx] = useState(0);
  const slide = data.slides[idx];
  const total = data.slides.length;
  const SlideHook = () => <div style={{ width: "100%", height: "100%", background: B.dark, borderRadius: 12, padding: "32px 28px", display: "flex", flexDirection: "column", justifyContent: "space-between", fontFamily: T.bodyFont, position: "relative", overflow: "hidden" }}><BrandWatermark variant="dark" position="left" /><BrandHeader variant="dark" /><div style={{ position: "relative", zIndex: 2 }}><div style={{ width: 40, height: 3, background: B.accent, borderRadius: 2, marginBottom: 20 }} /><p style={{ fontFamily: T.primaryFont, fontWeight: T.titleWeight, fontSize: T.titleLargeSize, color: B.white, lineHeight: T.titleLineHeight, margin: 0 }}>{slide.texto}</p></div><span style={{ position: "relative", zIndex: 2, fontSize: 12, color: B.primary }}>Desliza</span></div>;
  const SlideValor = () => <div style={{ width: "100%", height: "100%", background: B.white, borderRadius: 12, padding: "32px 28px", display: "flex", flexDirection: "column", justifyContent: "space-between", fontFamily: T.bodyFont, borderLeft: `4px solid ${B.accent}`, position: "relative", overflow: "hidden" }}><BrandWatermark variant="light" /><span style={{ position: "relative", zIndex: 2, fontFamily: T.primaryFont, fontWeight: T.titleWeight, fontSize: T.microSize, color: B.text, letterSpacing: 2, textTransform: "uppercase" }}>Señal {idx} de {total - 2}</span><div style={{ position: "relative", zIndex: 2 }}><p style={{ fontFamily: T.primaryFont, fontWeight: T.titleWeight, fontSize: T.titleSize, color: B.dark, lineHeight: T.titleLineHeight, margin: "0 0 14px" }}>{slide.titulo}</p><p style={{ fontSize: T.bodySize, color: B.secondary, lineHeight: T.bodyLineHeight, margin: 0 }}>{slide.cuerpo}</p></div><div style={{ position: "relative", zIndex: 2, display: "flex", alignItems: "center", justifyContent: "space-between" }}><span style={{ fontSize: T.microSize, color: B.text }}>megactivo.com</span><ProgressDots total={total} idx={idx} /></div></div>;
  const SlideRemate = () => <div style={{ width: "100%", height: "100%", background: B.dark, borderRadius: 12, padding: "32px 28px", display: "flex", flexDirection: "column", justifyContent: "center", fontFamily: T.bodyFont, position: "relative", overflow: "hidden" }}><BrandWatermark variant="dark" /><div style={{ position: "relative", zIndex: 2, width: 40, height: 3, background: B.primary, borderRadius: 2, marginBottom: 24 }} /><p style={{ position: "relative", zIndex: 2, fontFamily: T.secondaryFont, fontWeight: T.accentWeight, fontSize: 18, color: B.white, lineHeight: 1.5, margin: 0, fontStyle: "italic" }}>“{slide.texto}”</p></div>;
  const SlideCTA = () => <div style={{ width: "100%", height: "100%", background: B.white, borderRadius: 12, padding: "32px 28px", display: "flex", flexDirection: "column", justifyContent: "space-between", fontFamily: T.bodyFont, position: "relative", overflow: "hidden" }}><BrandWatermark variant="light" /><BrandHeader variant="light" /><div style={{ position: "relative", zIndex: 2 }}><p style={{ fontFamily: T.primaryFont, fontWeight: T.titleWeight, fontSize: 17, color: B.dark, lineHeight: 1.4, margin: "0 0 20px" }}>{slide.texto}</p><div style={{ background: B.dark, borderRadius: 8, padding: "12px 18px", display: "inline-block" }}><span style={{ color: B.accent, fontWeight: T.titleWeight, fontSize: T.smallSize }}>megactivo.com</span></div></div><span style={{ position: "relative", zIndex: 2, fontSize: T.microSize, color: B.text }}>El primer software contable colombiano con IA</span></div>;
  const renderSlide = () => slide.tipo === "hook" ? <SlideHook /> : slide.tipo === "valor" ? <SlideValor /> : slide.tipo === "remate" ? <SlideRemate /> : <SlideCTA />;
  return <div><div id="preview-carrusel" style={{ width: 400, height: 400, borderRadius: 12, overflow: "hidden" }}>{renderSlide()}</div><div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 16, marginTop: 14 }}><button onClick={() => setIdx(Math.max(0, idx - 1))} disabled={idx === 0} style={{ background: B.dark, border: "none", color: B.white, borderRadius: 8, padding: "8px 18px", cursor: idx === 0 ? "not-allowed" : "pointer", opacity: idx === 0 ? 0.4 : 1, fontFamily: T.bodyFont, fontSize: T.smallSize }}>Anterior</button><span style={{ fontSize: T.smallSize, color: B.text, fontFamily: T.bodyFont }}>{idx + 1} / {total}</span><button onClick={() => setIdx(Math.min(total - 1, idx + 1))} disabled={idx === total - 1} style={{ background: B.dark, border: "none", color: B.white, borderRadius: 8, padding: "8px 18px", cursor: idx === total - 1 ? "not-allowed" : "pointer", opacity: idx === total - 1 ? 0.4 : 1, fontFamily: T.bodyFont, fontSize: T.smallSize }}>Siguiente</button></div></div>;
}

function StoryView({ data }) {
  const [idx, setIdx] = useState(0);
  const frame = data.frames[idx];
  const FrameProblema = () => <div style={{ width: "100%", height: "100%", background: B.dark, borderRadius: 12, padding: "28px 24px", display: "flex", flexDirection: "column", justifyContent: "space-between", fontFamily: T.bodyFont, position: "relative", overflow: "hidden" }}><BrandWatermark variant="dark" /><BrandHeader variant="dark" meta="1 / 3" /><div style={{ position: "relative", zIndex: 2 }}><p style={{ fontFamily: T.primaryFont, fontWeight: T.titleWeight, fontSize: T.titleSize, color: B.white, lineHeight: T.titleLineHeight, margin: "0 0 20px" }}>{frame.texto}</p><div style={{ background: "rgba(110,193,228,0.12)", border: `1px solid ${B.primary}44`, borderRadius: 10, padding: "12px 16px" }}><p style={{ fontSize: T.microSize, color: B.primary, fontWeight: T.titleWeight, margin: "0 0 8px", textTransform: "uppercase", letterSpacing: 1 }}>Votación</p>{frame.poll.map((op, i) => <div key={i} style={{ background: i === 0 ? B.primary : "transparent", border: `1px solid ${B.primary}66`, borderRadius: 6, padding: "8px 14px", marginBottom: i === 0 ? 6 : 0 }}><span style={{ fontSize: T.smallSize, color: i === 0 ? B.dark : B.primary, fontWeight: i === 0 ? T.titleWeight : T.textWeight }}>{op}</span></div>)}</div></div><span style={{ position: "relative", zIndex: 2, fontSize: 10, color: "rgba(255,255,255,0.45)" }}>Continúa para ver más</span></div>;
  const FrameSolucion = () => <div style={{ width: "100%", height: "100%", background: B.lightBg, borderRadius: 12, padding: "28px 24px", display: "flex", flexDirection: "column", justifyContent: "space-between", fontFamily: T.bodyFont, position: "relative", overflow: "hidden" }}><BrandWatermark variant="light" /><BrandHeader variant="light" meta="2 / 3" /><div style={{ position: "relative", zIndex: 2, textAlign: "center" }}><Logo type="mark" variant="light" width={54} style={{ margin: "0 auto 16px" }} /><p style={{ fontFamily: T.primaryFont, fontWeight: T.titleWeight, fontSize: T.titleSize, color: B.dark, lineHeight: T.titleLineHeight, margin: "0 0 12px" }}>{frame.texto}</p><p style={{ fontSize: 12, color: B.text, fontStyle: "italic", margin: 0 }}>{frame.detalle}</p></div><div style={{ position: "relative", zIndex: 2, display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>{[0,1,2].map(i => <div key={i} style={{ width: 8, height: 8, borderRadius: "50%", background: i === 1 ? B.dark : B.text, opacity: i === 1 ? 1 : 0.3 }} />)}</div></div>;
  const FrameCTA = () => <div style={{ width: "100%", height: "100%", background: B.dark, borderRadius: 12, padding: "28px 24px", display: "flex", flexDirection: "column", justifyContent: "space-between", fontFamily: T.bodyFont, position: "relative", overflow: "hidden" }}><BrandWatermark variant="dark" /><BrandHeader variant="dark" meta="3 / 3" /><div style={{ position: "relative", zIndex: 2, textAlign: "center" }}><p style={{ fontFamily: T.primaryFont, fontWeight: T.titleWeight, fontSize: T.titleLargeSize, color: B.white, lineHeight: 1.3, margin: "0 0 20px" }}>{frame.texto}</p><div style={{ background: B.accent, borderRadius: 30, padding: "12px 24px", display: "inline-block" }}><span style={{ color: B.dark, fontWeight: T.titleWeight, fontSize: T.bodySize }}>{frame.link}</span></div></div><span style={{ position: "relative", zIndex: 2, fontSize: 10, color: "rgba(255,255,255,0.45)", textAlign: "center" }}>Ver enlace en bio</span></div>;
  const renderFrame = () => frame.tipo === "problema" ? <FrameProblema /> : frame.tipo === "solucion" ? <FrameSolucion /> : <FrameCTA />;
  return <div><div id="preview-story" style={{ width: 240, height: 420, borderRadius: 12, overflow: "hidden", margin: "0 auto" }}>{renderFrame()}</div><div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 16, marginTop: 14 }}><button onClick={() => setIdx(Math.max(0, idx - 1))} disabled={idx === 0} style={{ background: B.dark, border: "none", color: B.white, borderRadius: 8, padding: "8px 18px", cursor: idx === 0 ? "not-allowed" : "pointer", opacity: idx === 0 ? 0.4 : 1, fontFamily: T.bodyFont, fontSize: T.smallSize }}>Anterior</button><span style={{ fontSize: T.smallSize, color: B.text, fontFamily: T.bodyFont }}>Frame {idx + 1} / 3</span><button onClick={() => setIdx(Math.min(2, idx + 1))} disabled={idx === 2} style={{ background: B.dark, border: "none", color: B.white, borderRadius: 8, padding: "8px 18px", cursor: idx === 2 ? "not-allowed" : "pointer", opacity: idx === 2 ? 0.4 : 1, fontFamily: T.bodyFont, fontSize: T.smallSize }}>Siguiente</button></div></div>;
}

function GuionReelView({ data }) {
  const secciones = [{ tiempo: "0 a 3 seg", label: "GANCHO", color: B.accent, bg: "rgba(97,206,112,0.08)", contenido: data.gancho, overlay: true, overlayLabel: "TEXTO EN PANTALLA" }, { tiempo: "3 a 8 seg", label: "PROBLEMA", color: B.primary, bg: "rgba(110,193,228,0.08)", contenido: data.problema, overlay: false }, ...data.puntos.map((p, i) => ({ tiempo: `${8 + i * 10} a ${18 + i * 10} seg`, label: `PUNTO ${i + 1}: ${p.titulo.toUpperCase()}`, color: B.dark, bg: i % 2 === 0 ? "rgba(15,57,59,0.06)" : "rgba(15,57,59,0.03)", contenido: p.cuerpo, overlay: true, overlayLabel: p.overlay })), { tiempo: "40 a 55 seg", label: "CIERRE", color: B.primary, bg: "rgba(110,193,228,0.08)", contenido: data.cierre, overlay: false }, { tiempo: "55 a 60 seg", label: "CTA", color: B.accent, bg: "rgba(97,206,112,0.08)", contenido: data.cta, overlay: false }];
  return <div id="preview-reel" style={{ width: 400, fontFamily: T.bodyFont }}><div style={{ background: B.dark, borderRadius: "12px 12px 0 0", padding: "14px 20px", display: "flex", justifyContent: "space-between", alignItems: "center" }}><Logo variant="dark" width={100} /><span style={{ fontSize: 12, color: B.primary }}>{data.duracion}</span></div><div style={{ border: `1px solid ${B.dark}22`, borderTop: "none", borderRadius: "0 0 12px 12px", overflow: "hidden", position: "relative" }}><Logo type="mark" variant="light" watermark width={230} style={{ position: "absolute", right: -60, bottom: -55 }} />{secciones.map((s, i) => <div key={i} style={{ position: "relative", zIndex: 2, background: s.bg, borderBottom: i < secciones.length - 1 ? `1px solid ${B.dark}11` : "none", padding: "14px 20px" }}><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}><span style={{ fontFamily: T.primaryFont, fontWeight: T.titleWeight, fontSize: T.microSize, color: s.color, letterSpacing: 1.2, textTransform: "uppercase" }}>{s.label}</span><span style={{ fontSize: 10, color: B.text, background: `${B.dark}11`, borderRadius: 4, padding: "2px 8px" }}>{s.tiempo}</span></div>{s.overlay && s.overlayLabel && <div style={{ background: B.dark, borderRadius: 6, padding: "5px 10px", marginBottom: 7, display: "inline-block" }}><span style={{ fontSize: T.microSize, color: B.accent, fontWeight: T.titleWeight }}>Overlay: “{s.overlayLabel}”</span></div>}<p style={{ fontSize: T.smallSize, color: B.body, lineHeight: T.bodyLineHeight, margin: 0 }}>{s.contenido}</p></div>)}</div></div>;
}

function ReactDataRenderer({ data, formato }) {
  if (!data) return null;
  switch (formato) {
    case "post_estatico": return <PostEstaticoView data={data}></PostEstaticoView>;
    case "carrusel":      return <CarruselView data={data}></CarruselView>;
    case "story":         return <StoryView data={data}></StoryView>;
    case "guion_reel":    return <GuionReelView data={data}></GuionReelView>;
    default:
      return <pre className="rd-raw">{JSON.stringify(data, null, 2)}</pre>;
  }
}

